import csv
import io
from collections import defaultdict


def _parse_rows(reader, required_fields):
    """Iterate over DictReader rows, yielding valid (region, product, quantity, cents) tuples."""
    for row in reader:
        if not required_fields.issubset(row.keys()):
            continue
        region = row["region"]
        product = row["product"]
        if not region or not product:
            continue
        try:
            quantity = int(row["quantity"])
            cents = int(row["cents"])
        except (ValueError, TypeError):
            continue
        yield region, product, quantity, cents


def _accumulate_totals(rows):
    """Sum quantity and cents grouped by (region, product)."""
    totals = defaultdict(lambda: {"quantity": 0, "cents": 0})
    for region, product, quantity, cents in rows:
        key = (region, product)
        totals[key]["quantity"] += quantity
        totals[key]["cents"] += cents
    return totals


def _build_result(totals, min_quantity):
    """Convert totals dict to a sorted list of result dicts, filtering by min_quantity."""
    result = [
        {"region": region, "product": product, "quantity": sums["quantity"], "cents": sums["cents"]}
        for (region, product), sums in totals.items()
        if sums["quantity"] >= min_quantity
    ]
    result.sort(key=lambda r: (r["region"], r["product"]))
    return result


def aggregate_sales(csv_text: str, *, min_quantity: int = 0) -> list[dict]:
    """
    Parse CSV text with headers region, product, quantity, cents.
    Skip malformed rows. Group by (region, product), summing quantity and cents.
    Return rows sorted by region then product.

    Optional keyword-only argument:
        min_quantity: omit groups whose aggregate quantity is less than this value.
    """
    required_fields = {"region", "product", "quantity", "cents"}

    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None or not required_fields.issubset(set(reader.fieldnames)):
        return []

    rows = _parse_rows(reader, required_fields)
    totals = _accumulate_totals(rows)
    return _build_result(totals, min_quantity)

